package com.bbms.service;
import com.bbms.domain.*; import com.bbms.repo.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Clock; import java.time.LocalDate; import java.util.*;
@Service public class BloodBankService {
 private final BloodUnitRepository units; private final BloodRequestRepository requests; private final BloodIssueRepository issues; private final InventoryMovementRepository movements; private final BloodRequestEventRepository events;
 @Value("${bbms.training.mode:false}") private boolean trainingMode; private Clock clock=Clock.systemDefaultZone();
 public BloodBankService(BloodUnitRepository u,BloodRequestRepository r,BloodIssueRepository i,InventoryMovementRepository m,BloodRequestEventRepository e){units=u;requests=r;issues=i;movements=m;events=e;}
 @Autowired public void setClock(Clock clock){this.clock=clock;}
 public static final List<String> GROUPS=List.of("A+","A-","B+","B-","AB+","AB-","O+","O-");
 @Transactional public void issue(Long requestId){issue(requestId,"system");}
 @Transactional public void issue(Long requestId,String actor){BloodRequest req=requests.findByIdForUpdate(requestId).orElseThrow(()->new IllegalArgumentException("Request not found."));if(req.isDemoData()&&!trainingMode)throw new IllegalArgumentException("This archived placeholder request cannot be issued.");if(!req.getStatus().equals("APPROVED"))throw new IllegalArgumentException("Approve the request before issuing blood.");List<BloodUnit> stock=units.availableForIssue(req.getBloodGroup(),req.getComponent(),LocalDate.now(clock),req.isDemoData());int available=stock.stream().mapToInt(BloodUnit::getQuantity).sum();if(available<req.getQuantity())throw new IllegalArgumentException("Insufficient eligible "+req.getBloodGroup()+" "+req.getComponent()+" stock: "+available+" eligible units available; "+req.getQuantity()+" requested.");int left=req.getQuantity();StringBuilder batches=new StringBuilder();for(BloodUnit unit:stock){if(left==0)break;int before=unit.getQuantity();int taken=Math.min(left,before);unit.setQuantity(before-taken);if(batches.length()>0)batches.append(", ");batches.append(unit.getBatchId()).append(" × ").append(taken);movements.save(new InventoryMovement(unit,"ISSUED",-taken,unit.getQuantity(),(trainingMode?"TRAINING SYNTHETIC ISSUE — ":"Request ")+req.getPatientReference(),actor));left-=taken;}req.setStatus("ISSUED");issues.save(new BloodIssue(req,batches.toString(),req.getQuantity()));events.save(new BloodRequestEvent(req,"ISSUED","Issued "+req.getQuantity()+" eligible units from "+batches,actor));}
}
